use std::io::{self, BufRead};

struct P {
    t: Vec<String>,
    i: usize,
    out: Vec<String>,
}

impl P {
    fn peek(&self) -> Option<&str> {
        self.t.get(self.i).map(|s| s.as_str())
    }
    fn expr(&mut self) -> Result<(), ()> {
        self.term()?;
        while let Some(op) = self.peek() {
            if op == "+" || op == "-" {
                let o = op.to_string();
                self.i += 1;
                self.term()?;
                self.out.push(o);
            } else {
                break;
            }
        }
        Ok(())
    }
    fn term(&mut self) -> Result<(), ()> {
        self.pow()?;
        while let Some(op) = self.peek() {
            if op == "*" || op == "/" {
                let o = op.to_string();
                self.i += 1;
                self.pow()?;
                self.out.push(o);
            } else {
                break;
            }
        }
        Ok(())
    }
    fn pow(&mut self) -> Result<(), ()> {
        self.atom()?;
        if self.peek() == Some("^") {
            self.i += 1;
            self.pow()?;
            self.out.push("^".to_string());
        }
        Ok(())
    }
    fn atom(&mut self) -> Result<(), ()> {
        match self.peek() {
            Some("(") => {
                self.i += 1;
                self.expr()?;
                if self.peek() == Some(")") {
                    self.i += 1;
                    Ok(())
                } else {
                    Err(())
                }
            }
            Some(s) if s.as_bytes()[0].is_ascii_digit() => {
                let s = s.to_string();
                self.i += 1;
                self.out.push(s);
                Ok(())
            }
            _ => Err(()),
        }
    }
}

fn convert(line: &str) -> Option<String> {
    let mut t: Vec<String> = Vec::new();
    let c: Vec<char> = line.chars().collect();
    let mut i = 0;
    while i < c.len() {
        let ch = c[i];
        if ch.is_whitespace() {
            i += 1;
        } else if ch.is_ascii_digit() {
            let mut s = String::new();
            while i < c.len() && c[i].is_ascii_digit() {
                s.push(c[i]);
                i += 1;
            }
            t.push(s);
        } else if "+-*/^()".contains(ch) {
            t.push(ch.to_string());
            i += 1;
        } else {
            return None;
        }
    }
    let mut p = P { t, i: 0, out: vec![] };
    if p.expr().is_err() || p.i != p.t.len() {
        return None;
    }
    Some(p.out.join(" "))
}

fn main() {
    for line in io::stdin().lock().lines() {
        let line = line.unwrap();
        if line.trim().is_empty() {
            continue;
        }
        match convert(&line) {
            Some(s) => println!("{}", s),
            None => println!("error"),
        }
    }
}

